WITH exploded AS (SELECT id, plan, effective_from, currency, EXPLODE_OUTER(tier_limits) AS val FROM price_tiers) SELECT CASE WHEN val >= 63 THEN 'HIGH' ELSE 'LOW' END AS val_tier, currency, COUNT(CASE WHEN plan = 'starter' THEN 1 END) AS starter_count, COUNT(*) AS event_count, COUNT(*) AS event_count_2, SUM(CASE WHEN currency = 'THB' THEN val ELSE 0 END) AS thb_val, APPROX_PERCENTILE(val, 0.9) AS val_p90 FROM exploded GROUP BY GROUPING SETS ((CASE WHEN val >= 63 THEN 'HIGH' ELSE 'LOW' END, currency), (CASE WHEN val >= 63 THEN 'HIGH' ELSE 'LOW' END)) HAVING thb_val >= 0
